CREATE TABLE `sys_region` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `code` varchar(12) NOT NULL COMMENT '行政区划代码(国家标准)',
  `name` varchar(50) NOT NULL COMMENT '行政区划名称',
  `full_name` varchar(100) NOT NULL COMMENT '完整名称(包含上级)',
  `level` tinyint NOT NULL COMMENT '层级(1-省/直辖市 2-市/直辖市辖区 3-区县)',
  `parent_code` varchar(12) DEFAULT NULL COMMENT '父级行政区划代码',
  `region_type` tinyint DEFAULT '1' COMMENT '区域类型(1-省 2-直辖市 3-地级市 4-区县)',
  `status` tinyint DEFAULT '1' COMMENT '状态(1-有效 0-无效)',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code` (`code`),
  KEY `idx_level` (`level`),
  KEY `idx_parent_code` (`parent_code`),
  KEY `idx_region_type` (`region_type`)
) ENGINE=InnoDB AUTO_INCREMENT=3714 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='行政区划表';
