  `sku_code` varchar(64) DEFAULT NULL COMMENT '编码',
  `length` decimal(10,1) DEFAULT NULL COMMENT '长，单位cm',
  `width` decimal(10,1) DEFAULT NULL COMMENT '宽，单位cm',
  `height` decimal(10,1) DEFAULT NULL COMMENT '高，单位cm',
  `gross_weight` decimal(10,3) DEFAULT NULL COMMENT '毛重，单位kg',
  `net_weight` decimal(10,3) DEFAULT NULL COMMENT '净重，单位kg',
  `cost_price` decimal(10,2) DEFAULT NULL COMMENT '成本价（元）',
  `selling_price` decimal(10,2) DEFAULT NULL COMMENT '销售价（元）',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT NULL COMMENT '修改人',
  `update_time` datetime(3) DEFAULT NULL COMMENT '修改时间',
  `repair_status` tinyint DEFAULT '0' COMMENT '维修状态：0待送修 1送修中 2维修中 3已修复 4待回寄 5已回寄 6报废',
  `fault_type` varchar(100) DEFAULT NULL COMMENT '故障类型',
  `fault_desc` varchar(500) DEFAULT NULL COMMENT '故障描述',
  `repair_vendor` varchar(100) DEFAULT NULL COMMENT '维修单位',
  `send_repair_time` datetime DEFAULT NULL COMMENT '送修时间',
  `repair_finish_time` datetime DEFAULT NULL COMMENT '维修完成时间',
  `return_time` datetime DEFAULT NULL COMMENT '回寄时间',
  `repair_result` varchar(500) DEFAULT NULL COMMENT '维修结果',
  `repair_remark` varchar(500) DEFAULT NULL COMMENT '维修备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_sku_code` (`sku_code`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2051953646321217641 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='sku信息';
