--
-- Table structure for table `wms_item_sku_qr_pre`
--

DROP TABLE IF EXISTS `wms_item_sku_qr_pre`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wms_item_sku_qr_pre` (
  `id` bigint NOT NULL COMMENT '主键',
  `batch_no` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '生成批次号',
  `pre_code` varchar(80) COLLATE utf8mb4_general_ci NOT NULL COMMENT '预生成唯一编码，正式入库后作为sku_code',
  `item_id` bigint NOT NULL COMMENT '规格型号ID',
  `item_code` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '规格型号编码快照',
  `item_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '规格型号名称快照',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态：0未使用 1已使用 2作废 3过期',
  `expire_time` datetime DEFAULT NULL COMMENT '过期时间',
  `used_sku_id` bigint DEFAULT NULL COMMENT '正式入库后的wms_item_sku.id',
  `used_time` datetime DEFAULT NULL COMMENT '使用时间',
  `create_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_wms_item_sku_qr_pre_code` (`pre_code`) USING BTREE,
  KEY `idx_wms_item_sku_qr_pre_batch` (`batch_no`) USING BTREE,
  KEY `idx_wms_item_sku_qr_pre_item_status` (`item_id`,`status`) USING BTREE,
  KEY `idx_wms_item_sku_qr_pre_expire` (`status`,`expire_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='SKU二维码预生成表';
/*!40101 SET character_set_client = @saved_cs_client */;

